 public static function key(string $source):string{return'member_bank_'.substr(hash('sha256',$source),0,24);}
 public static function messages(string $locale):array{$en=explode('-',$locale,2)[0]==='en';$out=[];foreach(self::ENGLISH as$s=>$v)$out[self::key($s)]=$en?$v:$s;return$out;}
 public static function text(string $source,array $messages,array $values=[]):string{if(preg_match('/\AIBAN für ([A-Z]{2}) muss ([0-9]{2}) Zeichen ohne Leerzeichen enthalten\.\z/D',$source,$m)){$source='IBAN für {country} muss {length} Zeichen ohne Leerzeichen enthalten.';$values=['country'=>$m[1],'length'=>$m[2]]+$values;}elseif(preg_match('/\AIBAN für ([A-Z]{2}) darf nach Länderkennung und Prüfziffer nur Ziffern enthalten\.\z/D',$source,$m)){$source='IBAN für {country} darf nach Länderkennung und Prüfziffer nur Ziffern enthalten.';$values=['country'=>$m[1]]+$values;}$s=$messages[self::key($source)]??ManagerMessages::text($source,$messages);foreach($values as$k=>$v)$s=str_replace('{'.$k.'}',(string)$v,$s);return$s;}
